// Contenido del grado 9° (Estándares Básicos de Competencias en Lenguaje, MEN 2006; DBA de Lenguaje v2, MEN 2016)
import type { Grade } from './types';
const grade: Grade =
{id:'g9',n:9,title:'Literatura latinoamericana y argumentación',desc:'El boom y el realismo mágico, argumentar y debatir, y el español que hablamos.',units:[
{id:'g9u1',title:'Literatura latinoamericana',desc:'El realismo mágico, del libro a la pantalla y el lenguaje literario.',lessons:[
 {id:'g9u1l1',title:'El boom y el realismo mágico',time:50,std:'Determino en las obras literarias latinoamericanas, elementos textuales que dan cuenta de sus características estéticas, históricas y sociológicas, cuando sea pertinente.',dba:'DBA 3 (9°): analiza el lenguaje literario como una manifestación artística que permite crear ficciones y expresar pensamientos, emociones o sentimientos.',
  body:['En los años sesenta y setenta, varias novelas latinoamericanas se empezaron a leer y a traducir en todo el mundo al mismo tiempo. A ese fenómeno se le llamó el <b>boom</b> latinoamericano.',
   'Cuatro novelas famosas del boom: <i>La muerte de Artemio Cruz</i> (1962), de Carlos Fuentes (México); <i>Rayuela</i> (1963), de Julio Cortázar (Argentina); <i>La ciudad y los perros</i> (1963), de Mario Vargas Llosa (Perú), y <i>Cien años de soledad</i> (1967), de <b>Gabriel García Márquez</b> (Colombia).',
   'Muchas de esas obras usan el <b>realismo mágico</b>: lo extraordinario aparece en medio de la vida diaria. El narrador lo cuenta <b>sin sorpresa</b>, con el mismo tono con que cuenta un almuerzo.',
   'Un ejemplo de <i>Cien años de soledad</i>: en Macondo llueve durante casi cinco años, y una muchacha sube al cielo mientras ayuda a doblar unas sábanas. La voz que narra lo presenta como un hecho más.',
   'No hay que confundirlo con la <b>fantasía</b>. La fantasía inventa un mundo distinto al nuestro, con reglas propias: reinos, elfos, dragones. El realismo mágico ocurre en un mundo <b>real y reconocible</b>.',
   'García Márquez nació en <b>Aracataca</b> (Magdalena) en 1927. De ese pueblo bananero y de las historias de sus abuelos salió <b>Macondo</b>. Por eso Macondo tiene historia real: guerras civiles, una compañía bananera y una huelga.',
   'El realismo mágico no nació ni se quedó en Colombia. Antes del boom hubo <b>precursores</b>: el cubano <b>Alejo Carpentier</b>, el guatemalteco <b>Miguel Ángel Asturias</b> y el mexicano <b>Juan Rulfo</b>. Después, la chilena <b>Isabel Allende</b> siguió ese camino.'],
  bites:[{ej:'Hoy pasa algo parecido cuando una serie colombiana se vuelve tendencia en muchos países la misma semana.',check:{q:'¿Qué fue el boom latinoamericano?',o:['Un ritmo musical de los años sesenta','El momento en que el mundo empezó a leer novelas latinoamericanas','Un tipo de rima'],a:1,e:'En los años sesenta y setenta, esas novelas se tradujeron y se leyeron en todo el mundo.'}},
   {ojo:'Truco para recordar: cuatro novelas, cuatro países (México, Argentina, Perú y Colombia). La más famosa es la última, de 1967.'},
   {ej:'"Doña Elvira barría el andén mientras unas mariposas amarillas le peinaban el pelo." Lo raro (las mariposas) se cuenta igual que lo normal (barrer).',check:{q:'¿Cómo cuenta el narrador lo mágico en el realismo mágico?',o:['Con gritos y terror','Con calma, como algo normal','Explicando que era un sueño'],a:1,e:'El narrador no se asombra: lo extraordinario se cuenta como algo de todos los días.'}},
   {ojo:'Lo que vuelve mágica la escena no es solo el hecho raro, sino que nadie se asombra: "como todas las tardes", "nadie se extrañó".'},
   {ej:'Un reino con elfos y dragones es fantasía. Un pueblo del Magdalena donde llueven flores durante tres días, y la gente sale con paraguas, es realismo mágico.',check:{q:'¿Dónde ocurre el realismo mágico?',o:['En un mundo real y reconocible','En un planeta inventado','En un reino con dragones'],a:0,e:'La fantasía inventa otro mundo; el realismo mágico mete lo mágico en nuestro mundo.'}},
   {ej:'En 1982, García Márquez recibió el Premio Nobel de Literatura: fue el primer colombiano en ganarlo.',ojo:'Macondo no existe en el mapa, pero se parece mucho a Aracataca y a los pueblos del Caribe colombiano.'},
   {ej:'Sus obras: <i>El reino de este mundo</i> (1949), de Carpentier, que habló de "lo real maravilloso"; <i>Hombres de maíz</i> (1949), de Asturias, con mitos mayas; <i>Pedro Páramo</i> (1955), de Rulfo, donde se mezclan vivos y muertos, y <i>La casa de los espíritus</i> (1982), de Allende.',ojo:'<i>Pedro Páramo</i> salió doce años antes que <i>Cien años de soledad</i>: fue un precursor, no una copia.',check:{q:'¿Quién escribió <i>Pedro Páramo</i>, antes del boom?',o:['Isabel Allende','Juan Rulfo','Julio Cortázar'],a:1,e:'El mexicano Juan Rulfo lo publicó en 1955.'}}],
  key:'Realismo mágico: lo maravilloso contado como algo normal dentro de un mundo real y reconocible.',
  co:'En 1982 García Márquez recibió el Premio Nobel de Literatura. En su discurso, "La soledad de América Latina", explicó que la realidad desmesurada del continente era la que alimentaba su escritura.',
  act:{type:'mark',prompt:'Elige un color y marca lo real y cotidiano; con el otro, lo mágico que el narrador cuenta sin sorpresa.',cats:[{n:'Real y cotidiano',c:'#1F5FA8'},{n:'Mágico',c:'#8A4B6E'}],text:'En San Jerónimo del Río, [[doña Elvira abría la tienda a las seis|0]] y [[barría el andén|0]] mientras [[unas mariposas amarillas le peinaban el pelo|1]]. Ese martes [[llegó el camión de la leche|0]] y, como todas las tardes, [[el abuelo Tomás conversó con su hermano muerto|1]] en la mecedora del patio. Nadie se asombró cuando [[empezó a llover flores de guayacán durante tres días|1]]: [[los niños fueron al colegio|0]] con paraguas y [[el alcalde mandó barrer los pétalos|0]] antes de la misa.',e:'Fíjate en "Nadie se asombró" y en "como todas las tardes": el tono tranquilo es lo que convierte lo mágico en realismo mágico.'},
  quiz:[{q:'¿Qué novela de García Márquez, publicada en 1967, se convirtió en el gran símbolo del boom?',o:['Rayuela','Pedro Páramo','Cien años de soledad','La ciudad y los perros'],a:2,e:'"Cien años de soledad" (1967) cuenta la historia de los Buendía en Macondo. "Rayuela" es de Cortázar, "Pedro Páramo" de Rulfo y "La ciudad y los perros" de Vargas Llosa.',lv:'L'},
   {q:'En un cuento, una mujer cocina y su esposo, muerto hace diez años, le pide la sal desde la mesa. Ella se la pasa y sigue revolviendo la olla. ¿Qué rasgo del realismo mágico aparece?',o:['Lo sobrenatural produce terror','Lo mágico se narra como algo cotidiano, sin asombro','La historia ocurre en otro planeta','Al final se explica que todo era un sueño'],a:1,e:'La mujer no se asusta ni se sorprende: lo extraordinario convive con lo cotidiano.',lv:'I'},
   {q:'¿Por qué se dice que el realismo mágico no es fantasía pura?',o:['Porque no tiene elementos mágicos','Porque solo lo escribieron autores colombianos','Porque siempre ocurre en grandes ciudades','Porque parte de un mundo real, con su historia y sus conflictos, y allí introduce lo extraordinario'],a:3,e:'Macondo tiene guerras civiles, una compañía bananera y una huelga: detrás de lo mágico hay historia de Colombia.',lv:'C'}],
  tip:'Pida a cada estudiante que describa en cinco líneas una escena real de su casa o su barrio y le agregue un solo hecho mágico contado con total naturalidad.'},
 {id:'g9u1l2',title:'Del libro a la pantalla',time:50,std:'Interpreto manifestaciones artísticas no verbales y las relaciono con otras producciones humanas, ya sean artísticas o no.',dba:'DBA 4 (9°): reconoce en las producciones literarias su estructura y la identidad cultural que recrean, y las relaciona con otras expresiones artísticas.',
  body:['Adaptar es <b>traducir</b> una historia de un lenguaje a otro. La novela <b>cuenta</b> con palabras, y cada lector imagina a su manera. El cine y las series <b>muestran</b> con imágenes, sonido, actuación y montaje.',
   'La literatura tiene sus propios recursos: el <b>narrador</b> (por ejemplo, el omnisciente, que lo sabe todo), los capítulos, los párrafos, la descripción con adjetivos, el monólogo interior escrito y figuras como la metáfora o la hipérbole.',
   'El cine usa otros: los <b>planos</b>, los movimientos de cámara, la <b>banda sonora</b> (música y sonidos), la <b>voz en off</b>, el <b>montaje</b> (unir y ordenar las tomas) y el <b>fundido a negro</b> (la imagen se oscurece para pasar a otra escena u otro tiempo).',
   'Toda adaptación <b>conserva</b> algo (la trama, los personajes, algunas frases) y <b>cambia</b> algo: resume y elimina escenas. La voz del narrador se vuelve <b>voz en off</b>, y los pensamientos, un <b>primer plano</b> del rostro.',
   'También cambia la forma de mostrar el tiempo y el lugar. Los años pasan con maquillaje de vejez, vestuario, cambio de actores o un montaje de meses. El pueblo que el lector imagina se construye como <b>set</b> y se muestra en plano general.',
   'Cada toma usa un <b>plano</b>. Del más abierto al más cerrado: el <b>plano general</b> muestra todo el lugar; el <b>plano medio</b>, a la persona de la cintura hacia arriba; el <b>primer plano</b>, el rostro, y el <b>plano detalle</b>, un objeto o una mano.',
   'Una adaptación sigue un <b>proceso</b>: leer la obra y elegir las escenas, escribir el <b>guion</b>, dibujar el <b>guion gráfico</b> (una tira de cuadros con el plano, la acción y el sonido), rodar las escenas y, al final, hacer el montaje y agregar la música.'],
  bites:[{ej:'<i>Cien años de soledad</i> es una novela de 1967 y también una serie estrenada en 2024.',check:{q:'¿Qué hace la pantalla que no hace la novela?',o:['Contar solo con palabras','Mostrar con imágenes y sonido'],a:1,e:'La novela cuenta con palabras; el cine y las series muestran.'}},
   {ojo:'Pista rápida: si está en las páginas de un libro (capítulo, párrafo, narrador, metáfora), es un recurso literario.'},
   {ej:'Cuando la pantalla se pone negra y aparece otra época, eso es un fundido a negro.',check:{q:'La música y los sonidos de una película son…',o:['el montaje','la banda sonora','un capítulo'],a:1,e:'La banda sonora reúne la música y los sonidos.'}},
   {ej:'En el libro, el narrador dice lo que piensa un personaje. En la serie, la cámara se acerca a su cara y suena una música triste.',ojo:'Al comparar libro y serie, no busques una copia: pregúntate qué se ganó, qué se perdió y por qué se decidió así.'},
   {ej:'Para la serie de <i>Cien años de soledad</i> se construyó un Macondo de verdad, como set, en el Tolima.',check:{q:'¿Cómo muestra una serie que pasaron veinte años?',o:['Con maquillaje de vejez o cambio de actores','Con un capítulo escrito','Con una metáfora'],a:0,e:'La pantalla no puede decir "pasaron veinte años" como el narrador: lo muestra en los cuerpos y la ropa.'}},
   {ojo:'Truco: cuanto más cerrado el plano, más emoción se ve. Plano general = dónde; primer plano = qué siente.',check:{q:'¿Qué plano muestra el rostro de un personaje?',o:['Plano general','Primer plano','Plano medio'],a:1,e:'El primer plano encuadra la cara y deja ver las emociones.'}},
   {ej:'El guion gráfico se parece a un cómic de la película: cuadro 1, plano general del pueblo; cuadro 2, primer plano de Úrsula.',check:{q:'¿Qué se hace justo después de escribir el guion?',o:['Montar y agregar la música','Dibujar el guion gráfico','Leer la obra'],a:1,e:'Primero la lectura, luego el guion, después el guion gráfico, el rodaje y el montaje.'}}],
  key:'La novela cuenta, la pantalla muestra: toda adaptación conserva, cambia y decide.',
  co:'En diciembre de 2024 se estrenó la serie de "Cien años de soledad". García Márquez nunca aceptó adaptarla en vida; sus hijos la autorizaron con dos condiciones: que se rodara en Colombia y que se hablara en español.',
  act:{type:'map',kind:'table',prompt:'Completa el cuadro comparativo entre "Cien años de soledad" y su adaptación en serie: lleva cada tarjeta a su casilla.',slots:[{label:'Novela · cómo es Macondo',a:'Frases que cada lector imagina'},{label:'Serie · cómo es Macondo',a:'Un pueblo construido como set y un plano general'},{label:'Novela · paso del tiempo',a:'El narrador resume años en una línea'},{label:'Serie · paso del tiempo',a:'Cambio de actores y maquillaje de vejez'},{label:'Novela · pensamientos',a:'El narrador entra en la mente del personaje'},{label:'Serie · pensamientos',a:'Primer plano del rostro y voz en off'},{label:'Se conserva',a:'Los Buendía, Macondo y la historia central'},{label:'Por qué cambia',a:'La novela cuenta; la pantalla muestra'}],extra:['La serie copia el libro página por página','La novela usa banda sonora'],e:'Cada cambio tiene una razón: lo que el libro dice con palabras, la serie lo tiene que resolver con imagen y sonido.'},
  quiz:[{q:'En un guion gráfico, ¿qué plano muestra el rostro de un personaje ocupando casi toda la pantalla?',o:['Plano general','Plano medio','Primer plano','Plano de conjunto'],a:2,e:'El primer plano encuadra la cara y deja ver las emociones.',lv:'L'},
   {q:'En la novela, el narrador dice lo que piensa un personaje. En la serie, el personaje no habla, pero la cámara se acerca a su cara y suena una música triste. ¿Qué hizo el director?',o:['Eliminó el pensamiento','Tradujo el pensamiento a imagen y sonido','Cambió el final de la historia','Copió el texto tal cual'],a:1,e:'El primer plano y la música cumplen en pantalla la función que en el libro cumplía el narrador.',lv:'I'},
   {q:'Un compañero dice: "La serie es mala porque no cuenta todo lo que dice el libro". ¿Cuál es la respuesta más crítica?',o:['Una adaptación se juzga por cómo traduce la historia a otro lenguaje, no por copiarla completa','Tiene razón: una adaptación debe copiar cada página','Las series siempre son mejores que los libros','Un libro y una serie no se pueden comparar'],a:0,e:'Comparar sirve para analizar decisiones: qué se conserva, qué cambia y qué efecto logra cada cambio.',lv:'C'}],
  tip:'Proyecte el primer minuto de una adaptación y lean en voz alta el párrafo del libro que le corresponde; que los grupos anoten tres cosas que se conservan y tres que cambian.'},
 {id:'g9u1l3',title:'El lenguaje literario',time:50,std:'Determino en las obras literarias latinoamericanas, elementos textuales que dan cuenta de sus características estéticas, históricas y sociológicas, cuando sea pertinente.',dba:'DBA 3 y 6 (9°): analiza el lenguaje literario como manifestación artística e interpreta textos atendiendo al funcionamiento de la lengua y a su intención.',
  body:['El <b>lenguaje literario</b> no solo informa: busca un <b>efecto</b> en quien lee, como asombro, tristeza, humor o belleza. Para lograrlo, se aparta del uso común de las palabras con <b>figuras literarias</b>.',
   'La <b>metáfora</b> dice que una cosa <b>es</b> otra, sin palabra de comparación: <i>el río es una culebra de plata</i>. El <b>símil</b> las une con "como" o "igual que": <i>lento como una tarde de domingo</i>. Las dos crean imágenes nuevas.',
   'La <b>hipérbole</b> exagera para expresar intensidad o emoción: <i>te lo he dicho un millón de veces</i>. La <b>personificación</b> da rasgos o acciones humanas a lo que no es humano (<i>el reloj se burlaba de mi espera</i>) y lo vuelve vivo y cercano.',
   'La <b>anáfora</b> repite palabras al inicio de versos o frases, y así crea ritmo. La <b>antítesis</b> enfrenta ideas opuestas para resaltar el contraste: <i>tú ríes en la fiesta y yo lloro en la esquina</i>.',
   'Una buena <b>frase inicial</b> también es un recurso. <i>Cien años de soledad</i> empieza con un coronel frente al pelotón de fusilamiento que recuerda la tarde lejana en que su padre lo llevó a conocer el hielo.',
   'Ese comienzo es una <b>anticipación</b>: adelanta un hecho del futuro. Junta en una sola oración el futuro, el pasado y el asombro, y abre preguntas que obligan a seguir leyendo: ¿por qué lo van a fusilar?'],
  bites:[{ej:'"El bus sale a las seis" solo informa. "El bus se arrastraba como un gusano cansado" busca un efecto: que sientas lo lento del viaje.',check:{q:'¿Cuál frase usa lenguaje literario?',o:['La tienda cierra los domingos','La ciudad se despertó bostezando'],a:1,e:'Una ciudad no bosteza: la frase busca una imagen y un efecto.'}},
   {ojo:'Truco: si aparece "como", es símil; si una cosa simplemente ES la otra, es metáfora.',check:{q:'"Tus manos son dos palomas" es…',o:['Un símil','Una metáfora'],a:1,e:'No usa "como": dice que las manos SON palomas.'}},
   {ej:'"Tengo tanta hambre que me comería una vaca" (hipérbole). "La ciudad se despertó bostezando" (personificación).',ojo:'La hipérbole no es una mentira: nadie espera que la tomes al pie de la letra.'},
   {ej:'José Asunción Silva repite "Una noche, / una noche toda llena de perfumes…": eso es una anáfora.',check:{q:'"Tú ríes en la fiesta y yo lloro en la esquina" usa…',o:['Anáfora','Antítesis'],a:1,e:'Enfrenta opuestos: reír y llorar, fiesta y esquina.'}},
   {ej:'Piensa en la primera frase de tu serie favorita o de un video que te atrapó: en pocos segundos te hizo querer ver más.'},
   {ojo:'Anticipación no es contar el final: adelanta un hecho, pero deja la pregunta abierta.',check:{q:'¿Qué hace la anticipación?',o:['Adelanta un hecho del futuro','Repite palabras al inicio de cada verso'],a:0,e:'Muestra algo que pasará después y crea intriga.'}}],
  key:'Cada figura busca un efecto: preguntarse qué produce en el lector es tan importante como nombrarla.',
  co:'José Asunción Silva abre su "Nocturno" repitiendo "Una noche, / una noche toda llena de perfumes…": una anáfora que marca el ritmo del recuerdo.',
  act:{type:'fix',prompt:'Los apuntes de Mateo tienen errores al nombrar las figuras. Toca cada palabra equivocada y corrígela.',text:'"Lento como una tarde de domingo": {{símil|metáfora|anáfora}}, porque usa "como". "Tus manos son dos palomas": metáfora. "El río es una culebra de plata": {{metáfora|símil|hipérbole}}, porque dice que una cosa es otra. "Te lo he dicho un millón de veces": {{hipérbole|personificación|antítesis}}, porque exagera. "El reloj se burlaba de mi espera": {{personificación|anáfora|símil}}, porque el reloj actúa como persona. Repetir "Una noche" al inicio de los versos: {{anáfora|antítesis|metáfora}}. "Tú ríes en la fiesta y yo lloro en la esquina": antítesis.',e:'Con "como", símil; si una cosa ES otra, metáfora; si exagera, hipérbole; si un objeto actúa como persona, personificación; si se repite al inicio, anáfora.'},
  quiz:[{q:'"Tus manos son dos palomas" es un ejemplo de…',o:['Símil','Metáfora','Hipérbole','Anáfora'],a:1,e:'Identifica las manos con palomas sin usar "como": es una metáfora.',lv:'L'},
   {q:'En "Te lo he dicho un millón de veces", ¿qué efecto busca la hipérbole?',o:['Dar un dato exacto','Comparar dos cosas con "como"','Expresar impaciencia exagerando','Dar vida a un objeto'],a:2,e:'Nadie cuenta un millón de veces: la exageración transmite cansancio o molestia.',lv:'I'},
   {q:'"Muchos años después, frente al pelotón de fusilamiento…": ¿por qué este comienzo atrapa al lector?',o:['Porque anticipa un hecho grave del futuro y abre una pregunta que obliga a seguir leyendo','Porque explica todo el final de la novela','Porque usa palabras difíciles','Porque tiene rima consonante'],a:0,e:'La anticipación crea intriga: ¿por qué van a fusilarlo?, ¿qué pasó con el hielo?',lv:'C'}],
  tip:'Lleve cinco frases iniciales de novelas y cuentos; que los grupos voten cuál los obliga más a seguir leyendo y expliquen qué recurso usa.'}
]},
{id:'g9u2',title:'Argumentar',desc:'Tesis y argumentos, el debate y el ensayo corto.',lessons:[
 {id:'g9u2l1',title:'Tesis, argumentos y conclusión',time:50,std:'Produzco textos escritos que evidencian el conocimiento que he alcanzado acerca del funcionamiento de la lengua en situaciones de comunicación y el uso de las estrategias de producción textual.',dba:'DBA 8 (9°): produce textos escritos, como los argumentativos, que evidencian el conocimiento sobre el funcionamiento de la lengua y el uso de estrategias de producción textual.',
  body:['Un texto argumentativo quiere <b>convencer</b>. Su centro es la <b>tesis</b>: la idea que el autor defiende, dicha en una oración clara. Por ejemplo: <i>El celular debe guardarse durante las clases</i>.',
   'La tesis se sostiene con <b>argumentos</b>: razones que responden a la pregunta "¿por qué?". Los argumentos se apoyan en <b>datos</b>, <b>ejemplos</b> y citas de expertos. Una opinión sin razones ("porque sí") no convence a nadie.',
   'El argumento suele llegar después de la tesis, con <b>porque</b>, <b>ya que</b>, <b>pues</b> o <b>dado que</b>: <i>El colegio debería tener huerta</i> (tesis) <i>porque enseña de dónde vienen los alimentos</i> (argumento).',
   'La <b>conclusión</b> retoma la tesis al final y a veces propone una acción; suele empezar con <i>en conclusión</i> o <i>por todo esto</i>. El texto gana fuerza si responde al <b>contraargumento</b>: lo que diría quien piensa distinto.',
   'Cuidado con las <b>falacias</b>: razonamientos que parecen argumentos, pero hacen trampa. El <b>ad hominem</b> ataca a la persona y no a su idea. El <b>hombre de paja</b> deforma la postura contraria para atacarla fácil.',
   'La <b>apelación a la mayoría</b> da algo por cierto solo porque muchos lo hacen o lo creen. La <b>generalización apresurada</b> saca una regla de uno o dos casos: <i>a mi primo le fue mal, así que a todos les irá mal</i>.',
   'El <b>falso dilema</b> muestra solo dos opciones cuando hay más. La <b>pendiente resbaladiza</b> encadena consecuencias exageradas sin pruebas. La <b>falsa causa</b> cree que, porque algo pasó después de otra cosa, fue causado por ella.'],
  bites:[{ej:'Otras tesis: "Bogotá necesita más ciclovías". "El uniforme debería ser opcional".',check:{q:'¿Qué es la tesis?',o:['La idea que el autor defiende','Un dato con números','El título del texto'],a:0,e:'La tesis es la postura que el texto quiere demostrar.'}},
   {ojo:'Un buen argumento se puede comprobar. "Porque sí" o "porque todo el mundo lo sabe" no son razones.'},
   {ej:'"Bogotá necesita más ciclovías, ya que la bicicleta no contamina el aire."',check:{q:'En "Las ciclovías reducen el tráfico, porque muchos dejan el carro", ¿cuál es el argumento?',o:['Las ciclovías reducen el tráfico','Muchos dejan el carro'],a:1,e:'La razón llega después de "porque": ese es el argumento.'}},
   {ej:'Contraargumento y respuesta: "Algunos dirán que el celular sirve para investigar; sin embargo, en clase distrae más de lo que ayuda".',check:{q:'¿Qué es el contraargumento?',o:['Lo que diría quien piensa distinto','La conclusión del texto','Un ejemplo a favor'],a:0,e:'Es la idea contraria; responderla hace más fuerte tu tesis.'}},
   {ej:'Ad hominem: "No le hagas caso: siempre saca malas notas". Hombre de paja: "Los que defienden el celular quieren jugar todo el día".',check:{q:'"No le hagas caso: siempre saca malas notas" es…',o:['Un argumento válido','Un ad hominem'],a:1,e:'Ataca a la persona, no dice nada de su idea.'}},
   {ej:'Apelación a la mayoría: "Todos los colegios prohíben el celular, así que nosotros también".',ojo:'Que muchos lo hagan no lo vuelve verdad, y uno o dos casos no son una regla.'},
   {ej:'Falso dilema: "O lo prohibimos del todo o será un caos". Pendiente resbaladiza: "Si lo usamos en el descanso, pronto nadie estudiará y el colegio cerrará". Falsa causa: "Desde que llegó el celular bajaron las notas; entonces es su culpa".',ojo:'Un argumento válido, en cambio, da una razón pertinente apoyada en datos, ejemplos o fuentes confiables.',check:{q:'"O lo prohibimos del todo o será un caos" es…',o:['Un falso dilema','Una falsa causa','Un dato'],a:0,e:'Muestra solo dos opciones, pero hay más: por ejemplo, usarlo con guía del profesor.'}}],
  key:'Tesis (lo que defiendo), argumentos (por qué), datos y ejemplos (pruebas) y conclusión (entonces).',
  co:'En 2023 un informe de la Unesco pidió restringir los teléfonos inteligentes en las escuelas cuando no apoyan el aprendizaje; muchos colegios colombianos discuten el tema en sus manuales de convivencia.',
  act:{type:'classify',prompt:'Estas oraciones vienen de dos columnas de opinión sobre el celular en el colegio. Arrastra cada una al papel que cumple.',bins:['Tesis','Argumento','Ejemplo o dato','Conclusión'],items:[['El celular debería guardarse en un casillero durante las clases.',0],['Prohibir el celular en el colegio es un error.',0],['Las notificaciones interrumpen la concentración y después cuesta retomar la tarea.',1],['Bien guiado, el celular sirve para consultar, grabar y aprender.',1],['Prohibirlo no enseña a usarlo con responsabilidad.',1],['En 2023, un informe de la Unesco pidió restringir los teléfonos que no apoyan el aprendizaje.',2],['En química, 9.° B grabó un experimento con el celular y lo analizó cuadro por cuadro.',2],['En mi colegio, desde que guardamos los celulares, los descansos volvieron a ser de fútbol y conversación.',2],['Por todo esto, guardar el celular no es un castigo: es una forma de cuidar la atención.',3],['En conclusión, en lugar de prohibir, el colegio debería enseñar a usarlo bien.',3]],e:'La tesis toma posición; el argumento da una razón; el ejemplo o dato la prueba; la conclusión empieza con "por todo esto" o "en conclusión".'},
  quiz:[{q:'¿Qué es la tesis de un texto argumentativo?',o:['Un ejemplo que prueba algo','La idea principal que el autor defiende','La lista de fuentes consultadas','El título de la columna'],a:1,e:'La tesis es la postura que el texto quiere demostrar.',lv:'L'},
   {q:'"Las ciclovías reducen el tráfico, porque muchos trabajadores dejan el carro y van en bicicleta." ¿Cuál es el argumento?',o:['Las ciclovías','reducen el tráfico','porque','muchos trabajadores dejan el carro y van en bicicleta'],a:3,e:'La tesis es "las ciclovías reducen el tráfico"; la razón que la sostiene, introducida por "porque", es el argumento.',lv:'I'},
   {q:'Una columna dice: "El celular es malo porque sí, y punto". ¿Qué le falta para convencer?',o:['Una tesis','Argumentos que expliquen por qué','Un título llamativo','Más signos de exclamación'],a:1,e:'Hay una postura, pero "porque sí" no es una razón: sin argumentos la tesis no se sostiene.',lv:'C'}],
  tip:'Recorte una columna de opinión de un periódico colombiano y pida a los grupos subrayar con cuatro colores tesis, argumentos, ejemplos y conclusión.'},
 {id:'g9u2l2',title:'El debate',time:55,std:'Utilizo el diálogo y la argumentación para superar enfrentamientos y posiciones antagónicas.',dba:'DBA 5 y 7 (9°): valora los discursos orales de otros y construye intervenciones orales atendiendo al contexto, a los interlocutores y al propósito comunicativo.',
  body:['El <b>debate</b> es una discusión organizada sobre un tema polémico. Hay dos posturas, <b>a favor</b> y <b>en contra</b>, y un <b>moderador</b> que da la palabra, controla el tiempo y cuida el respeto.',
   'El moderador es <b>imparcial</b>: no toma partido por ningún equipo. Su trabajo es que las dos posturas hablen con las mismas reglas y el mismo tiempo.',
   'Cada intervención tiene un tiempo fijo y una estructura: presento mi <b>postura</b>, doy dos o tres <b>argumentos</b> con datos o ejemplos y cierro con una frase clara. Si se acaba mi tiempo, termino, aunque me falte algo.',
   'En la <b>réplica</b> respondo a los argumentos del otro equipo, no a la persona. Una buena réplica reconoce la idea y la contesta con pruebas: <i>Entiendo tu punto, pero los datos muestran otra cosa</i>.',
   'Debatir también es <b>escuchar</b>: tomar nota, respetar el <b>turno</b> y no interrumpir. Se gana con buenas razones, no con gritos ni burlas (tampoco del acento de nadie). A veces el mejor final es un <b>acuerdo</b>: el propósito es pensar mejor juntos.',
   'En un debate hay que saber <b>bloquear falacias</b>. Aparecen las que ya conoces y otras nuevas. La <b>apelación a la autoridad</b> cita a alguien famoso que no es experto en el tema: <i>un cantante dijo que el metro elevado es mejor</i>.',
   'La <b>apelación a la emoción</b> busca conmover en lugar de dar datos: <i>piensen en los niños que llorarán</i>. La <b>pregunta compleja</b> da por hecho algo no probado: <i>¿ya dejaste de mentir?</i> Para responder, nombra la falacia con calma y pide razones.'],
  bites:[{ej:'Tema polémico en Bogotá: ¿el metro debía ser elevado o subterráneo?',check:{q:'¿Quién da la palabra y controla el tiempo?',o:['El equipo a favor','El moderador','El público'],a:1,e:'El moderador organiza los turnos y cuida las reglas.'}},
   {ojo:'Imparcial = sin favorito. Un moderador que le da más tiempo a sus amigos deja de ser imparcial.'},
   {ej:'"Estoy a favor del metro elevado. Primero, es más barato. Segundo, se construye más rápido. Por eso, es la mejor opción para Bogotá."',check:{q:'Se acabó tu tiempo y te falta un argumento. ¿Qué haces?',o:['Sigo hablando hasta terminar','Termino y respeto el tiempo'],a:1,e:'Cumplir el tiempo es respetar el turno de los demás.'}},
   {ojo:'"Eso lo dices porque vives en el norte" no es una réplica: es un ataque a la persona (ad hominem).'},
   {ej:'En un debate del curso, los dos equipos terminaron de acuerdo en pedir más rutas de bus al colegio. ¡Eso también es ganar!',check:{q:'¿Con qué se gana un debate?',o:['Con buenas razones','Hablando más duro','Interrumpiendo al otro'],a:0,e:'Gritar o interrumpir no prueba nada; las razones sí.'}},
   {ojo:'Las que ya conoces: ad hominem, falso dilema, apelación a la mayoría y pendiente resbaladiza. También aparecen en los debates.',check:{q:'"Un cantante dijo que el metro elevado es mejor" es…',o:['Apelación a la autoridad','Un dato técnico'],a:0,e:'El cantante no es experto en transporte: su fama no es una prueba.'}},
   {ej:'Respuesta tranquila: "Eso es una apelación a la emoción. ¿Qué datos hay sobre el ruido?"',check:{q:'"¿Ya dejaste de copiar en los exámenes?" es…',o:['Una pregunta compleja','Una réplica respetuosa'],a:0,e:'Da por hecho que copiabas, algo que nadie ha probado.'}}],
  key:'Postura, argumentos, réplica y respeto por el turno: se discuten las ideas, no las personas.',
  co:'La primera línea del metro de Bogotá, en construcción, es elevada. Durante años la ciudad debatió si debía ser subterránea: más costosa y lenta de construir, pero con menos impacto sobre las calles.',
  act:{type:'record',prompt:'Prepara una intervención de un minuto a favor o en contra de que el metro de Bogotá sea elevado. Grábala, escúchate y evalúate con la rúbrica.',text:'Guía: <b>Postura</b>: "Estoy a favor (o en contra) de que el metro sea elevado". <b>Argumento 1</b> con un dato o un ejemplo. <b>Argumento 2</b> con otro dato o ejemplo. <b>Cierre</b>: una frase que resuma tu posición. Recuerda: 60 segundos, voz clara y ningún ataque personal.',max:60,rubric:['Postura clara','Argumentos con datos o ejemplos','Tono respetuoso','Volumen y ritmo','Cierre dentro del tiempo']},
  quiz:[{q:'¿Quién da la palabra y controla el tiempo en un debate?',o:['El público','El equipo a favor','El moderador','El que hable más duro'],a:2,e:'El moderador organiza los turnos y cuida que se cumplan las reglas.',lv:'L'},
   {q:'En un debate, Sara responde: "Eso lo dices porque vives en el norte". ¿Qué error comete?',o:['Ataca a la persona en lugar de responder su argumento','Da un dato falso','Respeta el turno','Hace una réplica sólida'],a:0,e:'Es un ataque personal (ad hominem): no dice nada sobre si el argumento es bueno o malo.',lv:'I'},
   {q:'¿Por qué un debate puede terminar en un acuerdo y aun así ser exitoso?',o:['Porque ganar o perder da igual','Porque el moderador lo ordena','Porque su propósito es examinar razones y tomar mejores decisiones, no solo vencer','Porque nadie argumentó'],a:2,e:'El debate sirve para pensar mejor en grupo; un acuerdo bien argumentado es un buen resultado.',lv:'C'}],
  tip:'Organice un debate con roles rotativos: moderador, dos equipos y dos observadores que llevan la cuenta de interrupciones y ataques personales.'},
 {id:'g9u2l3',title:'El ensayo corto',time:55,std:'Produzco textos escritos que evidencian el conocimiento que he alcanzado acerca del funcionamiento de la lengua en situaciones de comunicación y el uso de las estrategias de producción textual.',dba:'DBA 8 (9°): produce textos escritos, como los argumentativos, que evidencian el conocimiento sobre el funcionamiento de la lengua y el uso de estrategias de producción textual.',
  body:['El <b>ensayo</b> es un texto en prosa en el que el autor reflexiona sobre un tema y defiende una <b>postura propia</b> con argumentos. Es más personal que un informe, pero más ordenado que una opinión suelta.',
   'Un ensayo corto tiene tres párrafos: <b>introducción</b> (presenta el tema y la tesis), <b>desarrollo</b> (los argumentos, cada uno con su ejemplo o dato) y <b>conclusión</b> (retoma la tesis con otras palabras y deja una idea final).',
   'Un párrafo de desarrollo suele ir así: primero el argumento (<i>En primer lugar, la huerta enseña…</i>), luego el ejemplo que lo prueba (<i>Por ejemplo, en 7.° sembramos…</i>) y al final una consecuencia (<i>Por lo tanto…</i>).',
   'Conviene incluir un <b>contraargumento</b> y responderlo: <i>Algunos dirán que…; sin embargo…</i> Así muestras que conoces otras posturas, y tu tesis queda más fuerte.',
   'Los <b>conectores</b> cosen las ideas, y cada uno tiene una función: <b>orden</b> (<i>en primer lugar</i>), <b>adición</b> para sumar otra idea (<i>además</i>), <b>ejemplo</b> (<i>por ejemplo</i>) y <b>explicación</b> para aclarar (<i>es decir</i>).',
   'Otros conectores oponen o cierran: <b>contraste</b> (<i>sin embargo, no obstante, en cambio</i>), <b>concesión</b> cuando el resultado va contra lo esperado (<i>aunque, aun así</i>), <b>consecuencia</b> (<i>por lo tanto, por eso</i>) y <b>conclusión</b> (<i>en conclusión</i>).',
   'Escribir un ensayo es un <b>proceso</b>: elegir el tema y la postura, escribir la tesis, planear argumentos y ejemplos, hacer el borrador y <b>revisar</b>. ¿Se entiende la tesis? ¿Cada argumento tiene prueba? ¿Hay palabras repetidas u oraciones larguísimas? ¿Están bien tildes y puntos?'],
  bites:[{ej:'Tema: las ciclovías. Postura propia: "Bogotá debería tener más ciclovías".',check:{q:'¿Qué hace el autor de un ensayo?',o:['Reflexiona y defiende una postura propia','Solo copia datos de otros','Cuenta un cuento con personajes'],a:0,e:'El ensayo es personal, pero ordenado y con argumentos.'}},
   {ojo:'La tesis va al principio, en la introducción. La conclusión la retoma, pero con otras palabras.'},
   {ej:'"En primer lugar, la huerta enseña de dónde vienen los alimentos. Por ejemplo, en 7.° sembramos cilantro para el restaurante escolar. Por lo tanto, la huerta une la ciencia con la vida diaria."',check:{q:'¿Qué va después del argumento en un párrafo de desarrollo?',o:['El ejemplo que lo prueba','La bibliografía'],a:0,e:'Argumento, ejemplo y consecuencia, en ese orden.'}},
   {ej:'"Algunos dirán que las ciclovías quitan carriles a los carros; sin embargo, una vía que mueve más personas en menos espacio es un mejor uso de la calle."',check:{q:'¿Para qué sirve responder un contraargumento?',o:['Para alargar el texto','Para mostrar que conoces otras posturas y reforzar tu tesis'],a:1,e:'Anticiparte a las objeciones te da credibilidad.'}},
   {ej:'"La ciclovía mejora la salud; además, reduce la contaminación." "La ciclovía es un espacio público, es decir, es de todos."',check:{q:'¿Qué conector suma otra idea?',o:['Además','Sin embargo','En conclusión'],a:0,e:'"Además" es un conector de adición.'}},
   {ej:'Concesión: "Llovió toda la mañana; aun así, la ciclovía estuvo llena". Contraste: "La bicicleta no contamina; el carro, en cambio, sí".',ojo:'No confundas: "por lo tanto" dice qué pasa después (consecuencia); "sin embargo" dice lo contrario (contraste).'},
   {ojo:'Lee tu borrador en voz alta: si te quedas sin aire en una oración, está demasiado larga.',check:{q:'¿Qué se hace justo antes de entregar un ensayo?',o:['Revisar y corregir','Cambiar la tesis','Borrar los conectores'],a:0,e:'Revisar tesis, pruebas, repeticiones, tildes y puntos es el último paso.'}}],
  key:'Introducción con tesis, desarrollo con argumentos y conclusión que la retoma, unidos con conectores.',
  co:'La ciclovía dominical de Bogotá existe desde 1974 y ha sido copiada por ciudades de todo el mundo: un buen punto de partida para argumentar sobre la bicicleta en la ciudad.',
  act:{type:'write',prompt:'Escribe un ensayo corto de tres párrafos para responder: ¿debería Bogotá tener más ciclovías?',purpose:{q:'¿Cuál es tu postura?',o:['A favor: sí, más ciclovías','En contra: hay otras prioridades','Con condiciones: sí, pero…']},plan:[{q:'Mi tesis, en una oración:',ph:'Bogotá debería…'},{q:'Argumento 1 y su ejemplo o dato:',ph:'En primer lugar…'},{q:'Argumento 2 y su ejemplo o dato:',ph:'Además…'},{q:'Lo que diría alguien que piensa distinto y cómo le respondo:',ph:'Algunos dirán que… sin embargo…'},{q:'Idea final para la conclusión:',ph:'En conclusión…'}],min:150,checklist:['La tesis aparece en el primer párrafo','Cada argumento tiene un ejemplo o un dato','Usé al menos tres conectores distintos','Respondí a una idea contraria','La conclusión retoma la tesis sin copiarla igual','Revisé tildes, puntos y mayúsculas'],model:'Bogotá debería ampliar sus ciclovías, porque la bicicleta mejora la movilidad y la salud de la ciudad. En primer lugar, cada persona que pedalea es un carro o un puesto de bus menos en las horas pico; por ejemplo, muchos trabajadores del sur ya llegan en bicicleta a sus empleos. Además, pedalear todos los días es ejercicio gratuito. Algunos dirán que las ciclovías quitan carriles a los carros; sin embargo, una vía que mueve más personas en menos espacio es un mejor uso de la calle. En conclusión, más ciclovías no son un lujo, sino una inversión en una ciudad más sana y más ágil.',e:'Guarda tu ensayo: lo puedes usar en el debate de la próxima clase.'},
  quiz:[{q:'¿En qué parte de un ensayo corto va normalmente la tesis?',o:['En la introducción','En el desarrollo','En la conclusión','En la bibliografía'],a:0,e:'La introducción presenta el tema y anuncia la postura que se va a defender.',lv:'L'},
   {q:'"La ciclovía mejora la salud; ___, reduce la contaminación." ¿Qué conector completa mejor la idea?',o:['sin embargo','por ejemplo','además','en cambio'],a:2,e:'La segunda idea suma otro beneficio: se necesita un conector de adición.',lv:'I'},
   {q:'¿Por qué conviene incluir un contraargumento en un ensayo?',o:['Para confundir al lector','Para alargar el texto','Porque obliga a cambiar la tesis','Porque muestra que conoces otras posturas y, al responderlas, tu tesis queda más fuerte'],a:3,e:'Anticiparse a las objeciones y responderlas da credibilidad al ensayo.',lv:'C'}],
  tip:'Haga una revisión entre pares: cada estudiante subraya la tesis del ensayo de su compañero; si no la encuentra en el primer párrafo, el autor debe reescribir la introducción.'}
]},
{id:'g9u3',title:'Lengua y sociedad',desc:'Variantes del español, noticias falsas y símbolos.',lessons:[
 {id:'g9u3l1',title:'Las variantes del español',time:50,std:'Identifico en situaciones comunicativas auténticas algunas variantes lingüísticas de mi entorno, generadas por ubicación geográfica, diferencia social o generacional, profesión, oficio, entre otras.',dba:'DBA 6 (9°): interpreta textos atendiendo al funcionamiento de la lengua en situaciones de comunicación y al papel del interlocutor y del contexto.',
  body:['Todos hablamos español, pero no de la misma manera. Las <b>variantes</b> de una lengua cambian según la <b>región</b> (los <b>dialectos</b>), el grupo social, la edad y la situación en que hablamos.',
   'En Colombia se oye el <b>sumercé</b> de Boyacá y Cundinamarca, el <b>vos</b> de Medellín y Cali (<i>¿vos qué querés?</i>) y el <b>¡ajá!</b> de la Costa. También cambian la entonación y la pronunciación: en la Costa, la s final a menudo se aspira o desaparece.',
   'Cada región tiene su propio <b>léxico</b>, es decir, sus palabras. En Bogotá y el altiplano se dice <i>chino</i> (niño), <i>¡qué chirriado!</i> (¡qué bonito!), <i>¡qué boleta!</i> (¡qué vergüenza!), <i>¡qué chicharrón!</i> (¡qué problema!) y <i>¡ala!</i>, y se toman <i>onces</i> por la tarde.',
   'En Antioquia se oye <i>parce</i> (amigo), <i>¡avemaría, pues!</i>, <i>¿quiubo, pues?</i> y <i>¡qué charro!</i> (¡qué chistoso!). En la Costa Caribe se dice <i>¡ajá!, ¿y entonces?</i>, <i>pelao</i> (muchacho), <i>¡erda!</i> y <i>mamar gallo</i> (bromear, tomar del pelo).',
   'En Cali y el Valle se usan <i>¡oís, ve!</i>, <i>mirá, ve</i> y <i>dar un borondo</i> (dar una vuelta), y se toma un <i>cholado</i> bien frío. En los Santanderes se saluda con <i>¿qué hubo, mano?</i> Muchas de estas palabras ya viajaron a todo el país.',
   'Ninguna variante es <b>incorrecta</b> ni mejor que otra: cada una funciona dentro de su comunidad. Burlarse de cómo habla otra región es un <b>prejuicio lingüístico</b>.',
   'Lo que sí existe es la <b>adecuación</b>: en una exposición o un documento oficial se usa una variante más <b>estándar</b>, para que todos entiendan, sin avergonzarse del habla propia.'],
  bites:[{ej:'Tu abuela y tú viven en la misma casa, pero no hablan igual: ella dice "chévere" y tú, quizá, otras palabras. Esa es una variante por edad.',check:{q:'¿Qué es un dialecto?',o:['La variante de una región','Un idioma distinto al español','Un error al hablar'],a:0,e:'Un dialecto es la forma de hablar una lengua en una región.'}},
   {ej:'En Barranquilla, "¿cómo estás?" puede sonar "¿cómo etá?": la s final casi no suena.',ojo:'<i>Parce</i> salió de Medellín, pero hoy se oye en todo el país.'},
   {ojo:'En Bogotá también se desayuna <i>changua</i>: un caldo de leche con huevo y cilantro. Y, claro, se dice <i>sumercé</i>.',check:{q:'En Bogotá, "¡qué boleta!" significa…',o:['¡Qué vergüenza!','¡Qué bonito!'],a:0,e:'"¡Qué boleta!" se dice cuando algo da pena; "¡qué chirriado!" es "¡qué bonito!".'}},
   {ej:'"¡Erda, pelao, deja de mamar gallo!" (Costa). "¿Quiubo, parce? ¡Qué charro ese video!" (Antioquia).'},
   {ej:'El <i>cholado</i> es un postre de hielo raspado con frutas y leche condensada, típico de Cali.',check:{q:'En Cali, "dar un borondo" es…',o:['Dar una vuelta','Dar un regalo','Dar una mala noticia'],a:0,e:'Borondo es una vuelta, un paseo corto.'}},
   {ojo:'"Hablan mal" es un prejuicio. "Hablan distinto" es la verdad.',check:{q:'Un influenciador dice que en la Costa "hablan mal". ¿Qué es eso?',o:['Un prejuicio lingüístico','Una regla de la lengua'],a:0,e:'Ninguna variante es incorrecta: juzgarla así es un prejuicio.'}},
   {ej:'Con tus amigos: "¡Qué chirriado, parce!". En una exposición: "Me pareció un trabajo muy bonito".',check:{q:'¿Qué variante conviene en un documento oficial?',o:['Una más estándar, para que todos entiendan','Solo la jerga de mi barrio'],a:0,e:'Adecuarse es escoger cómo hablar según la situación.'}}],
  key:'Variantes regionales, sociales y de situación: ninguna es incorrecta; lo importante es adecuarse al contexto.',
  co:'El Instituto Caro y Cuervo publicó entre 1981 y 1983 el Atlas Lingüístico-Etnográfico de Colombia, que registró cómo se nombran las mismas cosas en cada región del país.',
  act:{type:'comic',prompt:'Cuatro amigos de distintas regiones preparan una exposición. Completa cada globo con lo que diría cada uno.',panels:[
   {who:'Valentina (Barranquilla)',face:'😄',say:'¡{{Ajá|Sumercé|Parce}}!, ¿y entonces? ¿Ya tienen listo el cartel?'},
   {who:'Samuel (Medellín)',face:'😅',say:'¡{{Avemaría, pues|Oís, ve|Erda}}! Todavía no, {{parce|sumercé|mano}}. Se me olvidó.'},
   {who:'Julián (Tunja)',face:'🙂',say:'Tranquilos. ¿{{Sumercé|Vos|Pelao}} quiere que traiga pan para las {{onces|borondo|changua de la noche}}?'},
   {who:'Mateo (Cali)',face:'😎',say:'¡{{Oís, ve|Ajá|Quiubo, pues}}, qué rico! Después damos un {{borondo|cholado|chicharrón}} por el barrio.'},
   {who:'La profe',face:'👩‍🏫',say:'En la exposición usen un español más {{estándar|incorrecto|regional}}, para que todos entiendan. ¡Y nadie se burla del acento de nadie!'}],e:'Cada uno habla su variante y todos se entienden; en la exposición se adecúan con un español estándar.'},
  quiz:[{q:'¿En qué región de Colombia es más típico el tratamiento "sumercé"?',o:['La Costa Caribe','El Pacífico','El altiplano cundiboyacense','Los Llanos Orientales'],a:2,e:'Sumercé (de "su merced") es muy propio de Boyacá, Cundinamarca y el campo bogotano.',lv:'L'},
   {q:'Una estudiante de Barranquilla dice "¡Ajá!, ¿y entonces?" y su compañero de Cali responde "¡Ve, qué bueno!". ¿Qué muestra esta conversación?',o:['Dos variantes regionales del mismo idioma','Que los dos hablan mal','Que no se pueden entender','Dos idiomas distintos'],a:0,e:'Hablan el mismo idioma con rasgos regionales distintos y se entienden sin problema.',lv:'I'},
   {q:'Un influenciador se burla de cómo se habla en la Costa y dice que "hablan mal". ¿Qué es lo más acertado?',o:['Tiene razón: solo el español de Bogotá es correcto','Hay que prohibir las expresiones regionales','Es un prejuicio: cada variante es válida en su comunidad; lo que importa es adecuarse a la situación','Todos deberían hablar como en Medellín'],a:2,e:'Juzgar una variante como "mala" es un prejuicio lingüístico; la adecuación depende del contexto, no de la región.',lv:'C'}],
  tip:'Pida a los estudiantes que entrevisten a un familiar de otra región y recojan cinco palabras que usen distinto; armen un mapa del habla del curso.'},
 {id:'g9u3l2',title:'Noticias falsas y verificación',time:50,std:'Retomo crítica y selectivamente la información que circula a través de los medios de comunicación masiva, para confrontarla con la que proviene de otras fuentes.',dba:'DBA 1 (9°): confronta los discursos de los medios de comunicación con los que interactúa para afianzar su punto de vista particular.',
  body:['Una <b>noticia falsa</b> (desinformación) imita la forma de una noticia real para engañar, asustar o conseguir clics. Se mueve rápido por redes sociales y cadenas de WhatsApp porque despierta <b>emociones fuertes</b>.',
   'Hay pistas para sospechar. <b>Fuente</b>: no tiene o cita a "un amigo que trabaja en…". <b>Fecha</b>: es vieja o no aparece. <b>Foto</b>: es de otro lugar o de otro año.',
   '<b>Tono</b>: es alarmista, con mayúsculas y frases como "¡URGENTE!" o "compártelo antes de que lo borren". <b>Datos</b>: son exagerados o imposibles de comprobar. Ya tienes las cinco pistas: fuente, fecha, foto, tono y datos.',
   'Para <b>verificar</b>, busca la noticia en medios reconocidos y en la fuente oficial, y revisa la fecha. Haz también una <b>búsqueda inversa</b> de la imagen: muestra dónde y cuándo se publicó antes esa foto.',
   'Puedes consultar verificadores como <b>Colombiacheck</b>, un medio colombiano que revisa afirmaciones y cadenas. Que muchos la hayan compartido o que traiga foto no prueba nada. Si no la puedes comprobar, <b>no la compartas</b>.',
   'Al final, cada noticia recibe un veredicto. Es <b>confiable</b> si viene de una fuente oficial o identificable, tiene fecha y otros medios la confirman. Es <b>falsa</b> si el hecho es inventado (un rumor, una cura milagrosa, un montaje) o la fuente oficial lo desmiente.',
   'Es <b>engañosa</b> si parte de un hecho real, pero lo deforma: una foto verdadera de otro año o de otro lugar, un titular que exagera un estudio o un dato viejo presentado como nuevo. No es totalmente inventada, y por eso cuesta más detectarla.'],
  bites:[{ej:'Cada tanto circula por WhatsApp que "Bogotá quedará sin agua un mes". Asusta, y por eso se reenvía sin pensar.',check:{q:'¿Por qué una noticia falsa se mueve tan rápido?',o:['Porque despierta emociones fuertes','Porque siempre es corta','Porque la publica el Gobierno'],a:0,e:'El miedo o la rabia hacen que compartamos antes de verificar.'}},
   {ej:'"Un primo de un amigo que trabaja en la Alcaldía dijo…": eso no es una fuente, porque nadie puede comprobar quién es.'},
   {ojo:'Truco: tres pistas empiezan por F (fuente, fecha y foto); las otras dos son tono y datos.',check:{q:'¿Cuál es una señal de alerta?',o:['Tiene fecha y autor','Dice "compártelo antes de que lo borren"','Cita el sitio oficial'],a:1,e:'La urgencia busca que no te detengas a verificar.'}},
   {ej:'Si dicen que hay toque de queda en Bogotá, busca el decreto en la página oficial de la Alcaldía.',check:{q:'¿Para qué sirve la búsqueda inversa de una imagen?',o:['Para saber dónde y cuándo se publicó antes la foto','Para ponerle filtros a la foto'],a:0,e:'Así descubres si la foto es vieja o de otro lugar.'}},
   {ojo:'"Tiene foto" o "me la mandaron veinte personas" no son pruebas.',check:{q:'No puedes comprobar una cadena. ¿Qué haces?',o:['La comparto por si acaso','No la comparto'],a:1,e:'Así se corta la cadena de desinformación.'}},
   {ej:'Confiable: el IDEAM publica una alerta por lluvias en su sitio, con fecha, y los noticieros la repiten. Falsa: un blog dice que la arepa diaria cura la gripa.',check:{q:'Una cura milagrosa que ningún médico respalda es…',o:['Confiable','Falsa'],a:1,e:'El hecho es inventado: es falsa.'}},
   {ej:'"Así quedó Bogotá tras la granizada de ayer": sí hubo granizada, pero la foto es de 2019. Es engañosa.',check:{q:'Un titular usa un estudio real, pero exagera lo que dice. Es…',o:['Engañosa','Falsa','Confiable'],a:0,e:'Parte de algo real y lo deforma: engañosa.'}}],
  key:'Fuente, fecha, foto, tono y datos: cinco pistas que se revisan antes de compartir.',
  co:'Cada tanto circulan por WhatsApp cadenas sobre Bogotá, como supuestos cortes de agua de un mes o toques de queda que nadie decretó; la Alcaldía y los verificadores las desmienten en sus canales oficiales.',
  act:{type:'choose',prompt:'Estos mensajes llegaron al grupo del curso. Elige tu veredicto o lo que harías.',items:[
   {s:'Un audio de WhatsApp dice que Bogotá quedará sin agua 30 días desde mañana. Lo cuenta "un amigo que trabaja en la Alcaldía". La Alcaldía no ha dicho nada.',o:['Confiable','Engañosa','Falsa'],a:2,e:'No hay fuente identificable y la fuente oficial no lo confirma: es falsa.'},
   {s:'Un portal publica "Así quedó Bogotá tras la granizada de ayer". Sí hubo granizada, pero la búsqueda inversa muestra que la foto es de 2019.',o:['Confiable','Engañosa','Falsa'],a:1,e:'El hecho es real, pero la foto es de otro año: engañosa.'},
   {s:'El IDEAM publica en su sitio oficial una alerta por lluvias, con fecha, y varios noticieros la repiten.',o:['Confiable','Engañosa','Falsa'],a:0,e:'Fuente oficial, fecha y confirmación de otros medios: confiable.'},
   {s:'Te llega una foto impactante de una inundación "en Soacha, hoy". ¿Qué haces primero?',o:['La reenvío a todos mis grupos','Hago una búsqueda inversa de la imagen','La creo, porque tiene foto'],a:1,e:'La búsqueda inversa muestra si la foto es de otro lugar o de otro año.'},
   {s:'Una cadena dice "¡URGENTE! Compártelo antes de que lo borren". No aparece en ningún medio ni en Colombiacheck.',o:['La comparto por si acaso','No la comparto','Le agrego más signos de exclamación'],a:1,e:'Si no se puede comprobar, no se comparte.'},
   {s:'Un titular dice "El 80 % de los jóvenes ya no lee", pero el estudio citado solo midió libros impresos.',o:['Confiable','Engañosa','Falsa'],a:1,e:'El estudio existe, pero el titular exagera lo que dice: engañosa.'}],e:'Fuente, fecha, foto, tono y datos: revisa antes de compartir.'},
  quiz:[{q:'¿Cuál de estas es una señal de alerta en un mensaje?',o:['Cita una fuente oficial con enlace','Tiene fecha y autor','Pide compartirlo "antes de que lo borren"','Aparece en varios medios reconocidos'],a:2,e:'Pedir que se comparta con urgencia busca que no te detengas a verificar.',lv:'L'},
   {q:'Una cadena muestra una foto de una inundación y dice que es de Bogotá ayer. Una búsqueda inversa revela que la foto es de 2017 y de otro país. ¿Cómo clasificas la cadena?',o:['Confiable, porque tiene foto','Engañosa: usa una imagen real fuera de contexto','Verdadera, porque se ve mucha agua','Una simple opinión'],a:1,e:'La foto existe, pero se presenta con un lugar y una fecha que no son los suyos: es contenido engañoso.',lv:'I'},
   {q:'¿Por qué las noticias falsas suelen usar un tono alarmista?',o:['Porque la emoción fuerte hace que compartamos sin pensar ni verificar','Porque los periodistas escriben así','Porque WhatsApp lo exige','Porque así los textos son más cortos'],a:0,e:'El miedo y la rabia aceleran el reenvío y apagan la duda.',lv:'C'}],
  tip:'Muestre una cadena real ya desmentida (sin datos personales) y rete a los grupos a verificarla en diez minutos con buscadores y sitios de verificación.'},
 {id:'g9u3l3',title:'Símbolos que hablan',time:50,std:'Comprendo los factores sociales y culturales que determinan algunas manifestaciones del lenguaje no verbal.',dba:'DBA 2 (9°): incorpora símbolos de orden deportivo, cívico, político, religioso, científico o publicitario en los discursos que produce, teniendo claro su uso dentro del contexto.',
  body:['Un <b>símbolo</b> es un signo cuyo significado se establece por <b>convención</b>, es decir, por acuerdo de una comunidad. Por ejemplo, acordamos que el amarillo, el azul y el rojo de la bandera representan a Colombia.',
   'El símbolo <b>no se parece</b> a lo que representa: su sentido hay que aprenderlo. Por eso, un mismo color puede significar cosas distintas según el <b>contexto</b>.',
   'Los símbolos <b>cívicos</b> representan a un país, una ciudad o el Estado: la bandera, el escudo con su cóndor, el himno, la banda presidencial. Los <b>deportivos</b>, del deporte: la camiseta de la Selección, los anillos olímpicos, la tarjeta roja, el silbato, la copa.',
   'Los símbolos <b>religiosos</b> representan una fe: la cruz y el rosario del cristianismo, la estrella de David del judaísmo, la media luna del islam. Los <b>científicos</b> representan conceptos de la ciencia: π, H₂O, ∞ y el trébol amarillo y negro de la radiactividad.',
   'Otros símbolos los vemos a diario: la <b>balanza</b> representa la justicia; la <b>paloma blanca</b>, la paz; las <b>flechas en círculo</b>, el reciclaje, y el bastón con una serpiente enrollada, la medicina.',
   'Al escribir o hablar podemos <b>incorporar</b> símbolos con intención: un afiche de reciclaje usa las flechas en círculo; una crónica de fútbol llama a la Selección "la tricolor" o "la amarilla", por su camiseta. Hay que saber qué significan y tratarlos con <b>respeto</b>.'],
  bites:[{ojo:'Un extranjero no sabe qué significa nuestra bandera hasta que alguien se lo explica: por eso es una convención.',check:{q:'¿Por qué la bandera representa a Colombia?',o:['Porque la comunidad lo acordó','Porque se parece al mapa del país'],a:0,e:'El sentido del símbolo viene de un acuerdo, no del parecido.'}},
   {ej:'El rojo en el semáforo es "pare"; en la tarjeta del árbitro, "expulsado"; en la bandera, la sangre de quienes lucharon por la independencia.'},
   {ej:'"La tarjeta roja del árbitro" es deportiva; "el himno nacional" es cívico.',check:{q:'¿Qué tipo de símbolo son los anillos olímpicos?',o:['Cívico','Deportivo','Científico'],a:1,e:'Representan los Juegos Olímpicos: son un símbolo deportivo.'}},
   {ojo:'Truco: π y H₂O parecen letras, pero en ciencias funcionan como símbolos: todos los científicos acordaron qué significan.'},
   {ej:'En las canecas del colegio verás las flechas en círculo del reciclaje; en los juzgados, la balanza.',check:{q:'¿Qué representa la paloma blanca?',o:['La paz','La justicia','La medicina'],a:0,e:'La paloma blanca es símbolo de paz.'}},
   {ej:'"La amarilla volvió a llenar el Metropolitano": la crónica usa la camiseta como símbolo de la Selección.',ojo:'Usar un símbolo como un trapo o una burla ofende, porque se desprecia lo que significa para la comunidad.',check:{q:'Un afiche de reciclaje debería usar…',o:['Las flechas en círculo','La estrella de David','La tarjeta roja'],a:0,e:'Ese es el símbolo que la comunidad asocia con reciclar.'}}],
  key:'El símbolo representa por convención: su sentido depende de la comunidad y del contexto.',
  co:'El escudo de Bogotá, concedido por Carlos V en 1548, muestra un águila negra coronada que sostiene una granada en cada garra, rodeada por nueve granadas de oro.',
  act:{type:'match',prompt:'Une cada símbolo con lo que representa.',pairs:[['⚖️ La balanza','La justicia'],['🕊️ La paloma blanca','La paz'],['♻️ Las flechas en círculo','El reciclaje'],['⚕️ El bastón con una serpiente','La medicina'],['☢️ El trébol amarillo y negro','La radiactividad'],['✡️ La estrella de David','El judaísmo'],['☪️ La media luna','El islam'],['🇨🇴 Amarillo, azul y rojo','Colombia'],['👕 "La amarilla"','La Selección Colombia']],e:'Ninguno se parece a lo que significa: los entendemos porque la comunidad los acordó.'},
  quiz:[{q:'¿Qué tipo de símbolo son los cinco anillos olímpicos?',o:['Cívico','Religioso','Deportivo','Científico'],a:2,e:'Representan los Juegos Olímpicos y la unión de los continentes en el deporte.',lv:'L'},
   {q:'En la crónica "La amarilla volvió a llenar el Metropolitano", ¿a qué se refiere "la amarilla"?',o:['A una bandera de peligro','A la camiseta de la Selección Colombia','A un taxi','A la tarjeta del árbitro'],a:1,e:'El Metropolitano de Barranquilla es la casa de la Selección, y su camiseta amarilla la representa.',lv:'I'},
   {q:'Un video de humor usa la bandera de Colombia como trapo para limpiar el piso. ¿Por qué molesta a tanta gente?',o:['Porque la tela se daña','Porque es un símbolo cívico que la comunidad reconoce y respeta; usarlo así desprecia lo que representa','Porque la bandera no tiene colores','Porque es un símbolo científico'],a:1,e:'El valor del símbolo es social: lo que ofende no es el objeto, sino lo que significa para la comunidad.',lv:'C'}],
  tip:'Pida a cada grupo diseñar un afiche para una campaña del colegio que incorpore dos símbolos y explique por escrito por qué los eligió.'}
]}
]};
export default grade;
